import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '@/utils/api';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Upload, Search, GraduationCap, Trash2 } from 'lucide-react';
import { toast } from 'sonner';
import { useAuth } from '@/contexts/AuthContext';

export default function StudentsPage() {
  const [students, setStudents] = useState([]);
  const [search, setSearch] = useState('');
  const [classFilter, setClassFilter] = useState('');
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [form, setForm] = useState({ roll_no: '', name: '', class_name: '', contact: '', email: '' });
  const { user } = useAuth();
  const navigate = useNavigate();

  const fetchStudents = () => {
    const params = new URLSearchParams();
    if (search) params.set('search', search);
    if (classFilter) params.set('class_name', classFilter);
    api.get(`/students?${params}`).then(r => setStudents(r.data)).catch(() => {}).finally(() => setLoading(false));
  };

  useEffect(() => { fetchStudents(); }, [search, classFilter]);
  useEffect(() => { api.get('/classes').then(r => setClasses(r.data)).catch(() => {}); }, []);

  const handleAdd = async (e) => {
    e.preventDefault();
    try {
      await api.post('/students', form);
      toast.success('Student added');
      setDialogOpen(false);
      setForm({ roll_no: '', name: '', class_name: '', contact: '', email: '' });
      fetchStudents();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to add student');
    }
  };

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post('/students/upload', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      toast.success(`Added ${res.data.added} students, ${res.data.skipped} skipped`);
      fetchStudents();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Upload failed');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this student?')) return;
    try {
      await api.delete(`/students/${id}`);
      toast.success('Student deleted');
      fetchStudents();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to delete');
    }
  };

  return (
    <div className="space-y-6" data-testid="students-page">
      {/* Header */}
      <div className="flex flex-col sm:flex-row gap-3 items-start sm:items-center justify-between">
        <div className="flex flex-1 gap-2 w-full sm:w-auto">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              data-testid="student-search-input"
              placeholder="Search by name or roll no..."
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={classFilter || 'all'} onValueChange={v => setClassFilter(v === 'all' ? '' : v)}>
            <SelectTrigger className="w-36" data-testid="class-filter-select">
              <SelectValue placeholder="All Classes" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Classes</SelectItem>
              {classes.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        <div className="flex gap-2">
          <label className="cursor-pointer">
            <input type="file" accept=".csv,.xlsx,.xls" onChange={handleUpload} className="hidden" data-testid="upload-students-input" />
            <Button variant="outline" asChild>
              <span><Upload className="w-4 h-4 mr-2" /> Upload CSV</span>
            </Button>
          </label>
          <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
            <DialogTrigger asChild>
              <Button data-testid="add-student-btn"><Plus className="w-4 h-4 mr-2" /> Add Student</Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Add New Student</DialogTitle>
              </DialogHeader>
              <form onSubmit={handleAdd} className="space-y-4 mt-2">
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label className="text-sm">Roll No *</Label>
                    <Input data-testid="student-roll-input" value={form.roll_no} onChange={e => setForm({ ...form, roll_no: e.target.value })} required />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Name *</Label>
                    <Input data-testid="student-name-input" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Class</Label>
                    <Input data-testid="student-class-input" value={form.class_name} onChange={e => setForm({ ...form, class_name: e.target.value })} placeholder="e.g. CS-A" />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Contact</Label>
                    <Input data-testid="student-contact-input" value={form.contact} onChange={e => setForm({ ...form, contact: e.target.value })} />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <Label className="text-sm">Email</Label>
                  <Input data-testid="student-email-input" type="email" value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} />
                </div>
                <Button type="submit" className="w-full" data-testid="submit-student-btn">Add Student</Button>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {/* Students Count */}
      <div className="flex items-center gap-2">
        <Badge variant="secondary" className="gap-1"><GraduationCap className="w-3 h-3" /> {students.length} Students</Badge>
      </div>

      {/* Students Table */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-24">Roll No</TableHead>
                <TableHead>Name</TableHead>
                <TableHead>Class</TableHead>
                <TableHead>Contact</TableHead>
                <TableHead>Email</TableHead>
                {user?.role === 'admin' && <TableHead className="w-16" />}
              </TableRow>
            </TableHeader>
            <TableBody>
              {students.map((s, i) => (
                <motion.tr
                  key={s.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.02 }}
                  className="cursor-pointer hover:bg-muted/50 border-b border-border"
                  onClick={() => navigate(`/students/${s.id}`)}
                  data-testid={`student-row-${s.roll_no}`}
                >
                  <TableCell className="font-mono text-sm font-medium">{s.roll_no}</TableCell>
                  <TableCell className="font-medium">{s.name}</TableCell>
                  <TableCell><Badge variant="outline" className="text-xs">{s.class_name || '-'}</Badge></TableCell>
                  <TableCell className="text-muted-foreground text-sm">{s.contact || '-'}</TableCell>
                  <TableCell className="text-muted-foreground text-sm">{s.email || '-'}</TableCell>
                  {user?.role === 'admin' && (
                    <TableCell>
                      <Button variant="ghost" size="icon" onClick={(e) => { e.stopPropagation(); handleDelete(s.id); }} data-testid={`delete-student-${s.roll_no}`}>
                        <Trash2 className="w-4 h-4 text-destructive" />
                      </Button>
                    </TableCell>
                  )}
                </motion.tr>
              ))}
              {students.length === 0 && (
                <TableRow><TableCell colSpan={6} className="text-center py-12 text-muted-foreground">No students found</TableCell></TableRow>
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  );
}
