import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import api from '@/utils/api';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Users, UserCheck, UserX, BookOpen, Clock, TrendingUp, Trophy, AlertCircle, Calendar as CalendarIcon } from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend
} from 'recharts';

const COLORS = ['#4F5BD5', '#0D9488', '#F59E0B', '#EF4444', '#8B5CF6'];

const StatCard = ({ title, value, icon: Icon, color, delay }) => (
  <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay, duration: 0.3 }}>
    <Card className="hover:shadow-lg transition-shadow duration-300 border-border/50 h-full">
      <CardContent className="p-5 flex items-center gap-4">
        <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${color}`}>
          <Icon className="w-6 h-6 text-white" />
        </div>
        <div>
          <p className="text-sm text-muted-foreground font-medium">{title}</p>
          <p className="text-2xl font-bold font-['Manrope'] tracking-tight">{value}</p>
        </div>
      </CardContent>
    </Card>
  </motion.div>
);

const InsightBox = ({ title, data, type }) => {
  if (!data) return null;
  const isPerformance = type === 'performance';
  const val = isPerformance ? `${data.score}/${data.max_score}` : `${data.percentage}%`;
  return (
    <div className="flex items-center justify-between p-3 rounded-lg bg-muted/40 mb-2">
      <div>
        <p className="text-sm font-semibold">{data.student?.name}</p>
        <p className="text-xs text-muted-foreground">{data.student?.class_name} • {data.student?.roll_no}</p>
        {isPerformance && <p className="text-xs text-muted-foreground mt-0.5">{data.subject?.name}</p>}
      </div>
      <Badge variant="outline" className={`font-mono ${isPerformance ? 'text-primary' : data.percentage > 75 ? 'text-emerald-500' : 'text-rose-500'}`}>
        {val}
      </Badge>
    </div>
  );
};

export default function Dashboard() {
  const [stats, setStats] = useState(null);
  const [insights, setInsights] = useState(null);
  const [classes, setClasses] = useState([]);
  const [subjects, setSubjects] = useState([]);
  
  const [classFilter, setClassFilter] = useState('');
  const [subjectFilter, setSubjectFilter] = useState('');
  const [dateFilter, setDateFilter] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get('/stats'),
      api.get('/classes'),
      api.get('/subjects')
    ]).then(([st, cl, su]) => {
      setStats(st.data);
      setClasses(cl.data);
      setSubjects(su.data);
    }).catch(() => {}).finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    const p = new URLSearchParams();
    if (classFilter) p.set('class_name', classFilter);
    if (subjectFilter) p.set('subject_id', subjectFilter);
    if (dateFilter) p.set('date', dateFilter); // API expansion friendly
    api.get(`/stats/insights?${p}`).then(r => setInsights(r.data)).catch(() => {});
  }, [classFilter, subjectFilter, dateFilter]);

  if (loading) {
    return <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" /></div>;
  }

  const trendData = stats?.attendance_trend || [];
  const classData = stats?.classes?.map(c => ({ name: c.class_name, value: c.count })) || [];

  const attendancePie = [
    { name: 'Present', value: stats?.present_today || 0 },
    { name: 'Absent', value: stats?.absent_today || 0 },
    { name: 'Half Day', value: stats?.half_day_today || 0 },
  ].filter(d => d.value > 0);

  return (
    <div className="space-y-6" data-testid="dashboard-page">
      {/* Filters Section */}
      <div className="flex flex-wrap gap-3 items-end bg-card p-4 rounded-xl border border-border/50 shadow-sm">
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Date (Trend)</p>
          <Input type="date" value={dateFilter} onChange={e => setDateFilter(e.target.value)} className="w-40" />
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Class</p>
          <Select value={classFilter || 'all'} onValueChange={v => setClassFilter(v === 'all' ? '' : v)}>
            <SelectTrigger className="w-36"><SelectValue placeholder="All Classes" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Classes</SelectItem>
              {classes.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Subject</p>
          <Select value={subjectFilter || 'all'} onValueChange={v => setSubjectFilter(v === 'all' ? '' : v)}>
            <SelectTrigger className="w-40"><SelectValue placeholder="All Subjects" /></SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Subjects</SelectItem>
              {subjects.map(s => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Total Students" value={stats?.total_students || 0} icon={Users} color="bg-primary" delay={0} />
        <StatCard title="Present Today" value={stats?.present_today || 0} icon={UserCheck} color="bg-emerald-500" delay={0.1} />
        <StatCard title="Absent Today" value={stats?.absent_today || 0} icon={UserX} color="bg-rose-500" delay={0.2} />
        <StatCard title="Total Subjects" value={stats?.total_subjects || 0} icon={BookOpen} color="bg-amber-500" delay={0.3} />
      </div>

      {/* Advanced Analytics Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
          <Card className="h-full">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm flex items-center gap-2"><Trophy className="w-4 h-4 text-amber-500" /> Performance Insights</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-xs font-semibold text-emerald-600 mb-2 uppercase tracking-wide mt-2">Highest Marks</p>
              {insights?.highest_mark ? <InsightBox title="Highest Marks" data={insights.highest_mark} type="performance" /> : <p className="text-sm text-muted-foreground py-2">No data</p>}
              
              <p className="text-xs font-semibold text-rose-600 mb-2 uppercase tracking-wide mt-4">Lowest Marks</p>
              {insights?.lowest_mark ? <InsightBox title="Lowest Marks" data={insights.lowest_mark} type="performance" /> : <p className="text-sm text-muted-foreground py-2">No data</p>}
            </CardContent>
          </Card>
        </motion.div>

        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}>
          <Card className="h-full">
            <CardHeader className="pb-2">
              <CardTitle className="text-sm flex items-center gap-2"><UserCheck className="w-4 h-4 text-emerald-500" /> Attendance Insights</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-xs font-semibold text-emerald-600 mb-2 uppercase tracking-wide mt-2">Highest Attendance</p>
              {insights?.best_attendance ? <InsightBox title="Best Attendance" data={insights.best_attendance} type="attendance" /> : <p className="text-sm text-muted-foreground py-2">No data</p>}
              
              <p className="text-xs font-semibold text-rose-600 mb-2 uppercase tracking-wide mt-4">Lowest Attendance</p>
              {insights?.worst_attendance ? <InsightBox title="Worst Attendance" data={insights.worst_attendance} type="attendance" /> : <p className="text-sm text-muted-foreground py-2">No data</p>}
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Charts Row */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.6 }} className="lg:col-span-8">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-base font-semibold flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-primary" /> Weekly Attendance Trend
              </CardTitle>
            </CardHeader>
            <CardContent>
              {trendData.length > 0 ? (
                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={trendData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                    <XAxis dataKey="date" tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <YAxis tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <Tooltip contentStyle={{ background: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: 8, fontSize: 12 }} />
                    <Legend wrapperStyle={{ fontSize: 12 }} />
                    <Bar dataKey="present" fill="#0D9488" radius={[4, 4, 0, 0]} name="Present" />
                    <Bar dataKey="absent" fill="#EF4444" radius={[4, 4, 0, 0]} name="Absent" />
                    <Bar dataKey="half_day" fill="#F59E0B" radius={[4, 4, 0, 0]} name="Half Day" />
                  </BarChart>
                </ResponsiveContainer>
              ) : <div className="h-64 flex items-center justify-center text-muted-foreground text-sm"><Clock className="w-5 h-5 mr-2" /> No attendance data.</div>}
            </CardContent>
          </Card>
        </motion.div>

        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.7 }} className="lg:col-span-4">
          <Card className="h-full">
            <CardHeader className="pb-2"><CardTitle className="text-base font-semibold">Today's Attendance</CardTitle></CardHeader>
            <CardContent>
              {attendancePie.length > 0 ? (
                <ResponsiveContainer width="100%" height={240}>
                  <PieChart>
                    <Pie data={attendancePie} cx="50%" cy="50%" innerRadius={55} outerRadius={85} paddingAngle={4} dataKey="value">
                      {attendancePie.map((_, i) => <Cell key={i} fill={['#0D9488', '#EF4444', '#F59E0B'][i]} />)}
                    </Pie>
                    <Tooltip contentStyle={{ background: 'hsl(var(--card))', border: '1px solid hsl(var(--border))', borderRadius: 8, fontSize: 12 }} />
                    <Legend wrapperStyle={{ fontSize: 12 }} />
                  </PieChart>
                </ResponsiveContainer>
              ) : <div className="h-60 flex items-center justify-center text-muted-foreground text-sm">No attendance marked today</div>}
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {classData.length > 0 && (
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-base font-semibold">Class Distribution</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3">
              {classData.map((c, i) => (
                <div key={c.name} className="p-4 rounded-xl bg-muted/50 text-center">
                  <p className="text-2xl font-bold font-['Manrope']" style={{ color: COLORS[i % COLORS.length] }}>{c.value}</p>
                  <p className="text-xs text-muted-foreground mt-1 font-medium">{c.name}</p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}
