import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '@/utils/api';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { ArrowLeft, Download, UserCheck, UserX, Clock, BookOpen } from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell, Legend, LineChart, Line
} from 'recharts';
import { exportToExcel, exportToPDF } from '@/utils/exportUtils';

const COLORS = ['#0D9488', '#EF4444', '#F59E0B'];

export default function StudentProfile() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [student, setStudent] = useState(null);
  const [attendance, setAttendance] = useState(null);
  const [marks, setMarks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      api.get(`/students/${id}`),
      api.get(`/attendance/student/${id}`),
      api.get(`/marks/student/${id}`)
    ]).then(([s, a, m]) => {
      setStudent(s.data);
      setAttendance(a.data);
      setMarks(m.data);
    }).catch(() => {}).finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" /></div>;
  if (!student) return <div className="text-center py-12 text-muted-foreground">Student not found</div>;

  const attPie = attendance?.summary ? [
    { name: 'Present', value: attendance.summary.present },
    { name: 'Absent', value: attendance.summary.absent },
    { name: 'Half Day', value: attendance.summary.half_day },
  ].filter(d => d.value > 0) : [];

  const attTrend = attendance?.records?.reduce((acc, r) => {
    const month = r.date?.substring(0, 7);
    if (!acc[month]) acc[month] = { month, present: 0, absent: 0, half_day: 0 };
    acc[month][r.status]++;
    return acc;
  }, {});
  const trendData = Object.values(attTrend || {}).sort((a, b) => a.month.localeCompare(b.month));

  const marksData = marks.map(m => ({
    subject: m.subject?.name || m.subject_id?.substring(0, 6),
    score: m.score, max: m.max_score, category: m.category
  }));

  const handleExport = () => {
    const data = [{
      Name: student.name, Roll_No: student.roll_no, Class: student.class_name,
      Contact: student.contact, Email: student.email,
      Attendance_Pct: attendance?.summary?.percentage + '%',
      Present: attendance?.summary?.present, Absent: attendance?.summary?.absent,
    }];
    marks.forEach(m => {
      data[0][`${m.subject?.name || 'Subject'}_Score`] = m.score;
      data[0][`${m.subject?.name || 'Subject'}_Category`] = m.category;
    });
    exportToExcel(data, `student_${student.roll_no}`);
  };

  return (
    <div className="space-y-6" data-testid="student-profile-page" id="student-profile-content">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate('/students')} data-testid="back-to-students">
          <ArrowLeft className="w-5 h-5" />
        </Button>
        <div className="flex-1">
          <h2 className="text-2xl font-bold font-['Manrope']">{student.name}</h2>
          <p className="text-sm text-muted-foreground">{student.roll_no} - {student.class_name}</p>
        </div>
        <Button variant="outline" onClick={handleExport} data-testid="export-student-report">
          <Download className="w-4 h-4 mr-2" /> Export
        </Button>
        <Button variant="outline" onClick={() => exportToPDF('student-profile-content', `student_${student.roll_no}`)} data-testid="export-student-pdf">
          PDF
        </Button>
      </div>

      {/* Info Cards */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card><CardContent className="p-4 text-center">
          <p className="text-xs text-muted-foreground">Attendance</p>
          <p className="text-2xl font-bold text-primary">{attendance?.summary?.percentage || 0}%</p>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <p className="text-xs text-muted-foreground">Present</p>
          <p className="text-2xl font-bold text-emerald-500">{attendance?.summary?.present || 0}</p>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <p className="text-xs text-muted-foreground">Absent</p>
          <p className="text-2xl font-bold text-rose-500">{attendance?.summary?.absent || 0}</p>
        </CardContent></Card>
        <Card><CardContent className="p-4 text-center">
          <p className="text-xs text-muted-foreground">Subjects</p>
          <p className="text-2xl font-bold text-amber-500">{marks.length}</p>
        </CardContent></Card>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Attendance Pie */}
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><UserCheck className="w-4 h-4 text-primary" /> Attendance Breakdown</CardTitle></CardHeader>
            <CardContent>
              {attPie.length > 0 ? (
                <ResponsiveContainer width="100%" height={220}>
                  <PieChart><Pie data={attPie} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={4} dataKey="value">
                    {attPie.map((_, i) => <Cell key={i} fill={COLORS[i]} />)}
                  </Pie><Tooltip /><Legend wrapperStyle={{ fontSize: 12 }} /></PieChart>
                </ResponsiveContainer>
              ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No attendance data</div>}
            </CardContent>
          </Card>
        </motion.div>

        {/* Attendance Trend */}
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Clock className="w-4 h-4 text-primary" /> Monthly Trend</CardTitle></CardHeader>
            <CardContent>
              {trendData.length > 0 ? (
                <ResponsiveContainer width="100%" height={220}>
                  <LineChart data={trendData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                    <XAxis dataKey="month" tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <YAxis tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <Tooltip />
                    <Line type="monotone" dataKey="present" stroke="#0D9488" strokeWidth={2} dot={{ r: 3 }} />
                    <Line type="monotone" dataKey="absent" stroke="#EF4444" strokeWidth={2} dot={{ r: 3 }} />
                  </LineChart>
                </ResponsiveContainer>
              ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No trend data</div>}
            </CardContent>
          </Card>
        </motion.div>

        {/* Marks Bar */}
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="lg:col-span-2">
          <Card>
            <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><BookOpen className="w-4 h-4 text-primary" /> Subject-wise Marks</CardTitle></CardHeader>
            <CardContent>
              {marksData.length > 0 ? (
                <ResponsiveContainer width="100%" height={240}>
                  <BarChart data={marksData}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                    <XAxis dataKey="subject" tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <YAxis tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                    <Tooltip />
                    <Bar dataKey="score" fill="#4F5BD5" radius={[4, 4, 0, 0]} name="Score" />
                    <Bar dataKey="max" fill="#E2E8F0" radius={[4, 4, 0, 0]} name="Max Score" />
                  </BarChart>
                </ResponsiveContainer>
              ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No marks data</div>}
            </CardContent>
          </Card>
        </motion.div>
      </div>

      {/* Contact Info */}
      <Card>
        <CardHeader className="pb-2"><CardTitle className="text-sm">Contact Information</CardTitle></CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-sm">
            <div><p className="text-muted-foreground text-xs">Phone</p><p className="font-medium">{student.contact || '-'}</p></div>
            <div><p className="text-muted-foreground text-xs">Email</p><p className="font-medium">{student.email || '-'}</p></div>
            <div><p className="text-muted-foreground text-xs">Class</p><p className="font-medium">{student.class_name || '-'}</p></div>
            <div><p className="text-muted-foreground text-xs">Roll No</p><p className="font-medium font-mono">{student.roll_no}</p></div>
          </div>
        </CardContent>
      </Card>

      {/* Detailed Tables */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-8">
        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm">Full Attendance Record</CardTitle></CardHeader>
          <CardContent className="max-h-80 overflow-auto p-0">
            <table className="w-full text-sm text-left">
              <thead className="sticky top-0 bg-card border-b z-10">
                <tr><th className="p-3 font-medium text-muted-foreground">Date</th><th className="p-3 text-right font-medium text-muted-foreground">Status</th></tr>
              </thead>
              <tbody>
                {attendance?.records?.length > 0 ? attendance.records.map((r, i) => (
                  <tr key={i} className="border-b last:border-0 hover:bg-muted/50">
                    <td className="p-3">{r.date}</td>
                    <td className="p-3 text-right">
                      <Badge variant="outline" className={`${r.status === 'present' ? 'text-emerald-500 border-emerald-500/30' : r.status === 'absent' ? 'text-rose-500 border-rose-500/30' : 'text-amber-500 border-amber-500/30'} capitalize`}>
                        {r.status.replace('_', ' ')}
                      </Badge>
                    </td>
                  </tr>
                )) : <tr><td colSpan="2" className="p-8 text-center text-muted-foreground">No attendance records found</td></tr>}
              </tbody>
            </table>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2"><CardTitle className="text-sm">Subject-wise Marks</CardTitle></CardHeader>
          <CardContent className="max-h-80 overflow-auto p-0">
            <table className="w-full text-sm text-left">
              <thead className="sticky top-0 bg-card border-b z-10">
                <tr><th className="p-3 font-medium text-muted-foreground">Subject</th><th className="p-3 font-medium text-muted-foreground">Score</th><th className="p-3 font-medium text-muted-foreground text-right">Category</th></tr>
              </thead>
              <tbody>
                {marksData.length > 0 ? marksData.map((m, i) => (
                  <tr key={i} className="border-b last:border-0 hover:bg-muted/50">
                    <td className="p-3 font-medium">{m.subject}</td>
                    <td className="p-3">{m.score} / {m.max}</td>
                    <td className="p-3 text-right"><Badge variant="outline" className="font-mono">{m.category}</Badge></td>
                  </tr>
                )) : <tr><td colSpan="3" className="p-8 text-center text-muted-foreground">No marks recorded</td></tr>}
              </tbody>
            </table>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
