import { useState, useEffect } from 'react';
import { format, subDays } from 'date-fns';
import api from '@/utils/api';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { CalendarIcon, Download, Share2, BarChart3, UserCheck, UserX, Clock, Image as ImageIcon } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import { exportToExcel, exportToCSV, exportToPDF, exportToImage, shareOnWhatsApp, generateDailyReportPDF } from '@/utils/exportUtils';

import { toast } from 'sonner';

const COLORS = ['#0D9488', '#EF4444', '#F59E0B'];

export default function ReportsPage() {
  const [fromDate, setFromDate] = useState(subDays(new Date(), 30));
  const [toDate, setToDate] = useState(new Date());
  const [dailyDate, setDailyDate] = useState(new Date());
  const [subjects, setSubjects] = useState([]);
  const [selectedSubject, setSelectedSubject] = useState('');
  const [classFilter, setClassFilter] = useState('');
  const [classes, setClasses] = useState([]);
  
  const [monthlyData, setMonthlyData] = useState([]);
  const [dailyData, setDailyData] = useState({ present: [], absent: [] });
  const [loading, setLoading] = useState(false);
  const [settings, setSettings] = useState(null);

  useEffect(() => {
    api.get('/settings').then(r => setSettings(r.data)).catch(() => {});
    api.get('/subjects').then(r => setSubjects(r.data)).catch(() => {});
    api.get('/classes').then(r => setClasses(r.data)).catch(() => {});
  }, []);

  const fetchReport = () => {
    setLoading(true);
    const mParams = new URLSearchParams({
      from_date: format(fromDate, 'yyyy-MM-dd'),
      to_date: format(toDate, 'yyyy-MM-dd'),
    });
    if (selectedSubject) mParams.set('subject_id', selectedSubject);
    if (classFilter) mParams.set('class_name', classFilter);
    
    const dParams = new URLSearchParams({ 
      date: format(dailyDate, 'yyyy-MM-dd'),
      class_name: classFilter || "all"
    });

    console.log("FRONTEND FETCH PARAMS:", classFilter || "all", format(dailyDate, 'yyyy-MM-dd'));

    Promise.all([
      api.get(`/attendance/monthly?${mParams}`),
      api.get(`/report?${dParams}`)
    ]).then(([m, d]) => {
      setMonthlyData(m.data);
      setDailyData(d.data);
    }).catch(() => {}).finally(() => setLoading(false));
  };

  useEffect(() => { fetchReport(); }, [fromDate, toDate, dailyDate, selectedSubject, classFilter]);

  const totalPresent = monthlyData.reduce((a, d) => a + d.present, 0);
  const totalAbsent = monthlyData.reduce((a, d) => a + d.absent, 0);
  const totalHalf = monthlyData.reduce((a, d) => a + d.half_day, 0);

  const pieData = [
    { name: 'Present', value: totalPresent },
    { name: 'Absent', value: totalAbsent },
    { name: 'Half Day', value: totalHalf },
  ].filter(d => d.value > 0);

  const barData = monthlyData.map(d => ({
    name: d.student?.roll_no || '', present: d.present, absent: d.absent, half_day: d.half_day, pct: d.percentage
  }));

  const handleDownloadReport = () => {
    generateDailyReportPDF(`daily_report_${format(dailyDate, 'yyyy-MM-dd')}`);
  };

  const handleExportDailyExcel = () => {
    const combinedData = [...dailyData.present, ...dailyData.absent];
    if (!combinedData.length) {
       toast.error("No data to export");
       return;
    }
    const cleanData = combinedData.map(d => ({
       'Roll No': d.rollNo,
       'Name': d.name,
       'Status': d.status
    }));
    exportToExcel(cleanData, `daily_attendance_${format(dailyDate, 'yyyy-MM-dd')}`);
  };

  const handleExportDailyCSV = () => {
    const combinedData = [...dailyData.present, ...dailyData.absent];
    exportToCSV(combinedData, `daily_attendance_${format(dailyDate, 'yyyy-MM-dd')}`);
  };

  const handleExportExcel = () => {
    const rows = monthlyData.map(d => ({
      Roll_No: d.student?.roll_no, Name: d.student?.name, Class: d.student?.class_name,
      Present: d.present, Absent: d.absent, Half_Day: d.half_day, Percentage: d.percentage + '%'
    }));
    exportToExcel(rows, `monthly_report_${format(fromDate, 'yyyy-MM-dd')}_to_${format(toDate, 'yyyy-MM-dd')}`);
  };

  const handleExportCSV = () => {
    const rows = monthlyData.map(d => ({
      Roll_No: d.student?.roll_no, Name: d.student?.name, Present: d.present, Absent: d.absent, Percentage: d.percentage
    }));
    exportToCSV(rows, `report_${format(fromDate, 'yyyy-MM-dd')}`);
  };

  const handleWhatsApp = () => {
    const text = `Monthly Attendance Report\nPeriod: ${format(fromDate, 'PP')} - ${format(toDate, 'PP')}\nTotal Present: ${totalPresent}\nTotal Absent: ${totalAbsent}\nStudents: ${monthlyData.length}`;
    shareOnWhatsApp(text);
  };

  const DatePicker = ({ date, setDate, label }) => (
    <div>
      <p className="text-xs text-muted-foreground mb-1 font-medium">{label}</p>
      <Popover>
        <PopoverTrigger asChild>
          <Button variant="outline" className="w-40 justify-start" data-testid={`report-${label.toLowerCase()}-picker`}>
            <CalendarIcon className="w-4 h-4 mr-2" />{format(date, 'PP')}
          </Button>
        </PopoverTrigger>
        <PopoverContent className="w-auto p-0"><Calendar mode="single" selected={date} onSelect={d => d && setDate(d)} /></PopoverContent>
      </Popover>
    </div>
  );

  return (
    <div className="space-y-6" data-testid="reports-page">
      <Tabs defaultValue="daily" className="space-y-4">
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <TabsList>
            <TabsTrigger value="daily">Daily Report</TabsTrigger>
            <TabsTrigger value="monthly">Monthly Report</TabsTrigger>
          </TabsList>

          <div className="flex flex-wrap gap-3 items-end">
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Class</p>
              <Select value={classFilter || 'all'} onValueChange={v => setClassFilter(v === 'all' ? '' : v)}>
                <SelectTrigger className="w-36" data-testid="report-class-select"><SelectValue placeholder="All" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Classes</SelectItem>
                  {classes.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Subject</p>
              <Select value={selectedSubject || 'all'} onValueChange={v => setSelectedSubject(v === 'all' ? '' : v)}>
                <SelectTrigger className="w-44" data-testid="report-subject-select"><SelectValue placeholder="All Subjects" /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Subjects</SelectItem>
                  {subjects.map(s => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {/* DAILY REPORT TAB */}
        <TabsContent value="daily" className="space-y-4">
          <div className="flex flex-wrap gap-2 items-center mb-4 bg-muted/20 p-2 rounded-lg border">
            <DatePicker date={dailyDate} setDate={setDailyDate} label="Date" />
            <div className="h-6 w-px bg-border mx-2" />
            <Button size="sm" variant="outline" onClick={handleDownloadReport}>
              <Download className="w-3.5 h-3.5 mr-1.5" /> PDF
            </Button>
            <Button size="sm" variant="outline" onClick={handleExportDailyExcel}>
              <Download className="w-3.5 h-3.5 mr-1.5" /> Excel
            </Button>
            <Button size="sm" variant="outline" onClick={handleExportDailyCSV}>
              <Download className="w-3.5 h-3.5 mr-1.5" /> CSV
            </Button>
            <Button size="sm" variant="outline" onClick={() => exportToImage(`daily_report_${format(dailyDate, 'yyyy-MM-dd')}`)}>
              <ImageIcon className="w-3.5 h-3.5 mr-1.5" /> Image
            </Button>
          </div>

          <div id="report-section" className="bg-card px-2 pb-6 pt-2 rounded-lg">
            <CardHeader className="text-center border-b border-border/50 pb-6 mb-6">
              <CardTitle className="text-2xl font-bold tracking-tight">{settings?.college_name || 'College Name'}</CardTitle>
              <p className="text-muted-foreground text-sm font-medium mt-1">Daily Attendance Report</p>
              <div className="flex justify-center gap-4 mt-3 text-sm">
                <Badge variant="outline">Class: {classFilter || 'All'}</Badge>
                <Badge variant="outline">Date: {format(dailyDate, 'PPP')}</Badge>
              </div>
            </CardHeader>
            <CardContent className="pt-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {dailyData.error ? (
                  <div className="col-span-full py-16 text-center">
                    <p className="text-muted-foreground text-lg">{dailyData.error}</p>
                    <p className="text-sm text-muted-foreground mt-2">Use the class filter dropdown at the top of the page.</p>
                  </div>
                ) : dailyData.present.length === 0 && dailyData.absent.length === 0 ? (
                  <div className="col-span-full py-16 text-center border rounded-lg bg-muted/20">
                    <p className="text-muted-foreground text-lg font-medium">No attendance found for selected class and date</p>
                  </div>
                ) : (
                  <>
                    {/* Present Students */}
                    <div className="border border-emerald-100 dark:border-emerald-900/30 rounded-lg overflow-hidden flex flex-col">
                      <div className="bg-emerald-50 dark:bg-emerald-900/20 px-4 py-3 border-b flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <UserCheck className="w-5 h-5 text-emerald-600 dark:text-emerald-400" />
                          <h3 className="font-semibold text-emerald-700 dark:text-emerald-300">Present Students</h3>
                        </div>
                        <Badge variant="outline" className="bg-white dark:bg-black font-bold">{dailyData.present.length}</Badge>
                      </div>
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead className="w-24">Roll No</TableHead>
                            <TableHead>Student Name</TableHead>
                            <TableHead className="text-right">Status</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {dailyData.present.map(r => (
                            <TableRow key={r.rollNo}>
                              <TableCell className="font-mono text-sm">{r.rollNo}</TableCell>
                              <TableCell className="font-medium">{r.name}</TableCell>
                              <TableCell className="text-right"><Badge className="bg-emerald-500 hover:bg-emerald-600 text-white shadow-sm">{r.status}</Badge></TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>

                    {/* Absent Students */}
                    <div className="border border-rose-100 dark:border-rose-900/30 rounded-lg overflow-hidden flex flex-col">
                      <div className="bg-rose-50 dark:bg-rose-900/20 px-4 py-3 border-b flex items-center justify-between">
                        <div className="flex items-center gap-2">
                          <UserX className="w-5 h-5 text-rose-600 dark:text-rose-400" />
                          <h3 className="font-semibold text-rose-700 dark:text-rose-300">Absent Students</h3>
                        </div>
                        <Badge variant="outline" className="bg-white dark:bg-black font-bold">{dailyData.absent.length}</Badge>
                      </div>
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead className="w-24">Roll No</TableHead>
                            <TableHead>Student Name</TableHead>
                            <TableHead className="text-right">Status</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {dailyData.absent.map(r => (
                            <TableRow key={r.rollNo}>
                              <TableCell className="font-mono text-sm">{r.rollNo}</TableCell>
                              <TableCell className="font-medium">{r.name}</TableCell>
                              <TableCell className="text-right"><Badge className="bg-rose-500 hover:bg-rose-600 text-white shadow-sm">{r.status}</Badge></TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </div>
                  </>
                )}
              </div>
            </CardContent>
          </div>
        </TabsContent>

        {/* MONTHLY REPORT TAB */}
        <TabsContent value="monthly" className="space-y-6" id="reports-content">
          <div className="flex flex-wrap gap-3 items-end">
            <DatePicker date={fromDate} setDate={setFromDate} label="From" />
            <DatePicker date={toDate} setDate={setToDate} label="To" />
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <Card><CardContent className="p-4 flex items-center gap-3"><UserCheck className="w-5 h-5 text-emerald-500" /><div><p className="text-xs text-muted-foreground">Present</p><p className="text-xl font-bold">{totalPresent}</p></div></CardContent></Card>
            <Card><CardContent className="p-4 flex items-center gap-3"><UserX className="w-5 h-5 text-rose-500" /><div><p className="text-xs text-muted-foreground">Absent</p><p className="text-xl font-bold">{totalAbsent}</p></div></CardContent></Card>
            <Card><CardContent className="p-4 flex items-center gap-3"><Clock className="w-5 h-5 text-amber-500" /><div><p className="text-xs text-muted-foreground">Half Day</p><p className="text-xl font-bold">{totalHalf}</p></div></CardContent></Card>
            <Card><CardContent className="p-4 flex items-center gap-3"><BarChart3 className="w-5 h-5 text-primary" /><div><p className="text-xs text-muted-foreground">Students</p><p className="text-xl font-bold">{monthlyData.length}</p></div></CardContent></Card>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
              <Card>
                <CardHeader className="pb-2"><CardTitle className="text-sm">Attendance Distribution</CardTitle></CardHeader>
                <CardContent>
                  {pieData.length > 0 ? (
                    <ResponsiveContainer width="100%" height={240}>
                      <PieChart><Pie data={pieData} cx="50%" cy="50%" innerRadius={55} outerRadius={85} paddingAngle={4} dataKey="value">
                        {pieData.map((_, i) => <Cell key={i} fill={COLORS[i]} />)}
                      </Pie><Tooltip /><Legend wrapperStyle={{ fontSize: 12 }} /></PieChart>
                    </ResponsiveContainer>
                  ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No data for this period</div>}
                </CardContent>
              </Card>
            </motion.div>

            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.1 }}>
              <Card>
                <CardHeader className="pb-2"><CardTitle className="text-sm">Per Student Attendance</CardTitle></CardHeader>
                <CardContent>
                  {barData.length > 0 ? (
                    <ResponsiveContainer width="100%" height={240}>
                      <BarChart data={barData}>
                        <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                        <XAxis dataKey="name" tick={{ fontSize: 10, fill: 'hsl(var(--muted-foreground))' }} />
                        <YAxis tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                        <Tooltip />
                        <Bar dataKey="present" stackId="a" fill="#0D9488" name="Present" />
                        <Bar dataKey="absent" stackId="a" fill="#EF4444" name="Absent" />
                        <Bar dataKey="half_day" stackId="a" fill="#F59E0B" name="Half Day" />
                      </BarChart>
                    </ResponsiveContainer>
                  ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No data</div>}
                </CardContent>
              </Card>
            </motion.div>
          </div>

          <div className="flex flex-wrap gap-2">
            <Button onClick={handleExportExcel} data-testid="export-excel-btn"><Download className="w-4 h-4 mr-2" /> Excel</Button>
            <Button variant="outline" onClick={handleExportCSV} data-testid="export-csv-btn"><Download className="w-4 h-4 mr-2" /> CSV</Button>
            <Button variant="outline" onClick={() => exportToPDF('reports-content', 'monthly_report')} data-testid="export-pdf-btn"><Download className="w-4 h-4 mr-2" /> PDF</Button>
            <Button variant="outline" onClick={handleWhatsApp} data-testid="share-whatsapp-btn"><Share2 className="w-4 h-4 mr-2" /> WhatsApp</Button>
          </div>

          <Card>
            <CardHeader className="py-3 px-4"><CardTitle className="text-sm">Monthly Attendance Summary</CardTitle></CardHeader>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Roll No</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Class</TableHead>
                    <TableHead>Present</TableHead>
                    <TableHead>Absent</TableHead>
                    <TableHead>Half Day</TableHead>
                    <TableHead className="text-right">Percentage</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {monthlyData.map(d => (
                    <TableRow key={d.student_id} className="hover:bg-muted/50">
                      <TableCell className="font-mono text-sm">{d.student?.roll_no}</TableCell>
                      <TableCell className="font-medium">{d.student?.name}</TableCell>
                      <TableCell>{d.student?.class_name}</TableCell>
                      <TableCell className="text-emerald-600">{d.present}</TableCell>
                      <TableCell className="text-rose-600">{d.absent}</TableCell>
                      <TableCell className="text-amber-600">{d.half_day}</TableCell>
                      <TableCell className="text-right">
                        <Badge variant={d.percentage >= 75 ? 'default' : d.percentage >= 50 ? 'secondary' : 'destructive'} className="text-xs">
                          {d.percentage}%
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                  {monthlyData.length === 0 && <TableRow><TableCell colSpan={7} className="text-center py-8 text-muted-foreground">No attendance data for this period</TableCell></TableRow>}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* HIDDEN REPORT TEMPLATE FOR IMAGE EXPORT */}
      <div style={{ position: 'absolute', left: '-9999px', top: '-9999px', width: '800px', backgroundColor: 'white', color: 'black', padding: '40px', fontFamily: 'sans-serif' }} id="report-template">
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <h1 style={{ fontSize: '24px', fontWeight: 'bold', margin: '0 0 10px 0' }}>{settings?.college_name || 'Guru Gobind Singh Polytechnic'}</h1>
          <h2 style={{ fontSize: '20px', fontWeight: 'normal', margin: '0 0 20px 0' }}>Daily Attendance Report</h2>
          <div style={{ fontSize: '16px', display: 'flex', flexDirection: 'column', gap: '5px' }}>
            <p style={{ margin: 0 }}><strong>Class:</strong> {classFilter || 'All Classes'}</p>
            <p style={{ margin: 0 }}><strong>Date:</strong> {format(dailyDate, 'PPP')}</p>
          </div>
        </div>

        <div style={{ marginBottom: '30px' }}>
          <h3 style={{ fontSize: '18px', fontWeight: 'bold', color: '#0d9488', borderBottom: '2px solid #0d9488', paddingBottom: '5px', marginBottom: '15px' }}>
            ✔ Total Present: {dailyData.present.length}
          </h3>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
             {dailyData.present.map((r, i) => (
               <li key={r.student_id} style={{ fontSize: '14px', padding: '8px 0', borderBottom: '1px solid #eee' }}>
                 {i + 1}. {r.student?.roll_no} - {r.student?.name}
               </li>
             ))}
             {dailyData.present.length === 0 && <li style={{ fontSize: '14px', color: '#666' }}>No present students</li>}
          </ul>
        </div>

        <div>
           <h3 style={{ fontSize: '18px', fontWeight: 'bold', color: '#e11d48', borderBottom: '2px solid #e11d48', paddingBottom: '5px', marginBottom: '15px' }}>
            ❌ Total Absent: {dailyData.absent.length}
          </h3>
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
             {dailyData.absent.map((r, i) => (
               <li key={r.student_id} style={{ fontSize: '14px', padding: '8px 0', borderBottom: '1px solid #eee' }}>
                 {i + 1}. {r.student?.roll_no} - {r.student?.name}
               </li>
             ))}
             {dailyData.absent.length === 0 && <li style={{ fontSize: '14px', color: '#666' }}>No absent students</li>}
          </ul>
        </div>
      </div>
    </div>
  );
}
