import * as XLSX from 'xlsx';
import jsPDF from 'jspdf';
import 'jspdf-autotable';
import html2canvas from 'html2canvas';

export const exportToExcel = (data, filename) => {
  if (!data || data.length === 0) {
    alert("No data to export");
    return;
  }
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Report');
  XLSX.writeFile(wb, `${filename}.xlsx`);
};

export const exportToCSV = (data, filename) => {
  if (!data || data.length === 0) {
    alert("No data to export");
    return;
  }
  const header = "Roll No,Name,Status\n";
  const csv = header + data.map(row => `${row.rollNo},${row.name},${row.status}`).join("\n");
  const blob = new Blob([csv], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${filename}.csv`;
  a.click();
  URL.revokeObjectURL(url);
};

export const exportToPDF = async (elementId, filename) => {
  const el = document.getElementById(elementId);
  if (!el) return;
  const canvas = await html2canvas(el, { scale: 2, useCORS: true });
  const pdf = new jsPDF('p', 'mm', 'a4');
  const w = pdf.internal.pageSize.getWidth();
  const h = (canvas.height * w) / canvas.width;
  pdf.addImage(canvas.toDataURL('image/png'), 'PNG', 0, 0, w, h);
  pdf.save(`${filename}.pdf`);
};

export const generateDailyReportPDF = async (filename) => {
  const element = document.getElementById("report-section");
  if (!element) {
    alert("No data to export");
    return;
  }
  
  // Await the Canvas layer physically hooking rendering states implicitly
  setTimeout(async () => {
    const canvas = await html2canvas(element, {
      scale: 2,
      useCORS: true
    });

    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");

    const imgWidth = 210;
    const imgHeight = (canvas.height * imgWidth) / canvas.width;

    pdf.addImage(imgData, "PNG", 0, 0, imgWidth, imgHeight);
    pdf.save(`${filename}.pdf`);
  }, 100);
};

export const shareOnWhatsApp = (text) => {
  window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
};

export const exportToImage = async (filename) => {
  const el = document.getElementById("report-section");
  if (!el) {
    alert("No data to export");
    return;
  }
  // Let the browser paint fully before capture naturally targeting the wrapped div explicitly
  setTimeout(async () => {
    const canvas = await html2canvas(el, { scale: 2, useCORS: true, backgroundColor: '#ffffff' });
    const link = document.createElement("a");
    link.download = `${filename}.png`;
    link.href = canvas.toDataURL("image/png");
    link.click();
  }, 100);
};
