import { useState, useEffect } from 'react';
import api from '@/utils/api';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogDescription, DialogFooter } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Separator } from '@/components/ui/separator';
import { toast } from 'sonner';
import { useTheme } from '@/contexts/ThemeContext';
import { useSettings } from '@/contexts/SettingsContext';
import {
  Palette, BookOpen, Users, Sliders, Plus, Trash2, Save, Download,
  AlertTriangle, Database, ImagePlus, ServerCog
} from 'lucide-react';

export default function AdminPanel() {
  const { darkMode, toggleDark } = useTheme();
  const { settings: globalSettings, refreshSettings } = useSettings();
  const [settings, setSettings] = useState(null);
  const [subjects, setSubjects] = useState([]);
  const [users, setUsers] = useState([]);
  const [saving, setSaving] = useState(false);
  const [downloading, setDownloading] = useState(false);
  const [resetting, setResetting] = useState(false);
  const [seeding, setSeeding] = useState(false);
  const [resetDialogOpen, setResetDialogOpen] = useState(false);
  const [logoPreview, setLogoPreview] = useState('');

  const [subjectDialog, setSubjectDialog] = useState(false);
  const [subForm, setSubForm] = useState({ name: '', code: '', class_name: '', faculty_id: '' });
  const [userDialog, setUserDialog] = useState(false);
  const [userForm, setUserForm] = useState({ email: '', password: '', name: '', role: 'faculty' });

  useEffect(() => {
    if (globalSettings) {
      setSettings(globalSettings);
      if (globalSettings.logo_url) setLogoPreview(globalSettings.logo_url);
    }
  }, [globalSettings]);

  useEffect(() => {
    api.get('/subjects').then(r => setSubjects(r.data)).catch(() => {});
    api.get('/users').then(r => setUsers(r.data)).catch(() => {});
  }, []);

  const saveSettings = async () => {
    setSaving(true);
    try {
      const res = await api.put('/settings', settings);
      setSettings(res.data);
      await refreshSettings();
      toast.success('Settings saved and applied globally!');
    } catch {
      toast.error('Failed to save settings');
    } finally {
      setSaving(false);
    }
  };

  const handleLogoUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const preview = URL.createObjectURL(file);
    setLogoPreview(preview);
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post('/admin/upload-logo', fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      setSettings({ ...settings, logo_url: res.data.logo_url });
      await refreshSettings();
      toast.success('Logo uploaded successfully');
    } catch {
      toast.error('Upload failed (max 5MB)');
    }
  };

  const handleResetBranding = async () => {
    if (!window.confirm('Reset college branding and theme to default?')) return;
    setSaving(true);
    try {
      const defaultSettings = {
        ...settings,
        college_name: 'Guru Gobind Singh Polytechnic',
        department_name: 'Nashik',
        logo_url: 'https://customer-assets.emergentagent.com/job_marks-portal-11/artifacts/h0m13o6i_GGSP-logo.png',
      };
      const res = await api.put('/settings', defaultSettings);
      setSettings(res.data);
      setLogoPreview('');
      await refreshSettings();
      toast.success('Branding reset to default');
    } catch {
      toast.error('Failed to reset branding');
    } finally {
      setSaving(false);
    }
  };

  const handleDownloadProject = async () => {
    setDownloading(true);
    try {
      const res = await api.get('/admin/download-project', { responseType: 'blob' });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'college-erp-project.zip';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      toast.success('Project downloaded!');
    } catch {
      toast.error('Download failed');
    } finally {
      setDownloading(false);
    }
  };

  const handleResetDatabase = async () => {
    setResetting(true);
    try {
      await api.post('/admin/reset-database');
      toast.success('Database reset successfully');
      setResetDialogOpen(false);
      api.get('/subjects').then(r => setSubjects(r.data));
      api.get('/users').then(r => setUsers(r.data));
    } catch {
      toast.error('Reset failed');
    } finally {
      setResetting(false);
    }
  };

  const handleSeedData = async () => {
    setSeeding(true);
    try {
      const res = await api.post('/admin/seed-sample-data');
      toast.success(res.data.message);
      api.get('/subjects').then(r => setSubjects(r.data));
    } catch {
      toast.error('Seeding failed');
    } finally {
      setSeeding(false);
    }
  };

  const handleAddSubject = async (e) => {
    e.preventDefault();
    try {
      await api.post('/subjects', subForm);
      toast.success('Subject added');
      setSubjectDialog(false);
      setSubForm({ name: '', code: '', class_name: '', faculty_id: '' });
      api.get('/subjects').then(r => setSubjects(r.data));
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed');
    }
  };

  const handleDeleteSubject = async (id) => {
    try {
      await api.delete(`/subjects/${id}`);
      toast.success('Subject deleted');
      setSubjects(subjects.filter(s => s.id !== id));
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed');
    }
  };

  const handleAddUser = async (e) => {
    e.preventDefault();
    try {
      await api.post('/auth/register', userForm);
      toast.success('User added');
      setUserDialog(false);
      setUserForm({ email: '', password: '', name: '', role: 'faculty' });
      api.get('/users').then(r => setUsers(r.data));
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed');
    }
  };

  const handleDeleteUser = async (id) => {
    if (!window.confirm('Delete this user?')) return;
    try {
      await api.delete(`/users/${id}`);
      toast.success('User deleted');
      setUsers(users.filter(u => u.id !== id));
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed');
    }
  };

  if (!settings) return <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-3 border-primary border-t-transparent rounded-full animate-spin" /></div>;

  return (
    <div className="space-y-6" data-testid="admin-panel">
      <Tabs defaultValue="branding" className="space-y-4">
        <TabsList className="grid grid-cols-5 w-full max-w-2xl">
          <TabsTrigger value="branding" data-testid="tab-branding"><Palette className="w-4 h-4 mr-1.5 hidden sm:inline" /> Branding</TabsTrigger>
          <TabsTrigger value="subjects" data-testid="tab-subjects"><BookOpen className="w-4 h-4 mr-1.5 hidden sm:inline" /> Subjects</TabsTrigger>
          <TabsTrigger value="users" data-testid="tab-users"><Users className="w-4 h-4 mr-1.5 hidden sm:inline" /> Users</TabsTrigger>
          <TabsTrigger value="marks" data-testid="tab-marks-settings"><Sliders className="w-4 h-4 mr-1.5 hidden sm:inline" /> Marks</TabsTrigger>
          <TabsTrigger value="system" data-testid="tab-system"><ServerCog className="w-4 h-4 mr-1.5 hidden sm:inline" /> System</TabsTrigger>
        </TabsList>

        {/* Branding Tab */}
        <TabsContent value="branding" className="space-y-4">
          <Card>
            <CardHeader><CardTitle className="text-base flex items-center gap-2"><Palette className="w-5 h-5 text-primary" /> College Branding</CardTitle></CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <Label>College Name</Label>
                  <Input data-testid="settings-college-name" value={settings.college_name || ''} onChange={e => setSettings({ ...settings, college_name: e.target.value })} />
                </div>
                <div className="space-y-1.5">
                  <Label>Department Name</Label>
                  <Input data-testid="settings-dept-name" value={settings.department_name || ''} onChange={e => setSettings({ ...settings, department_name: e.target.value })} />
                </div>
                <div className="space-y-1.5 sm:col-span-2">
                  <Label>College Logo</Label>
                  <div className="flex items-center gap-5">
                    {logoPreview && (
                      <img src={logoPreview} alt="Logo" className="w-20 h-20 rounded-xl object-contain border border-border bg-background p-1" />
                    )}
                    <div className="flex-1">
                      <label className="cursor-pointer">
                        <input type="file" accept="image/*" onChange={handleLogoUpload} className="hidden" data-testid="settings-logo-upload" />
                        <Button variant="outline" asChild>
                          <span><ImagePlus className="w-4 h-4 mr-2" /> Upload Logo</span>
                        </Button>
                      </label>
                      <p className="text-xs text-muted-foreground mt-2">PNG, JPG or SVG (max 5MB)</p>
                    </div>
                  </div>
                </div>
                <div className="space-y-1.5">
                  <Label>Splash Duration (seconds)</Label>
                  <Input data-testid="settings-splash-duration" type="number" min={1} max={10} value={settings.splash_duration || 3} onChange={e => setSettings({ ...settings, splash_duration: parseInt(e.target.value) || 3 })} />
                </div>
              </div>

              <Separator />

              <div className="space-y-3">
                <h4 className="text-sm font-semibold">Theme</h4>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div className="space-y-1.5">
                    <Label>Primary Color</Label>
                    <div className="flex gap-2 items-center">
                      <input type="color" value={settings.theme?.primary_color || '#4F5BD5'} onChange={e => setSettings({ ...settings, theme: { ...settings.theme, primary_color: e.target.value } })} className="w-10 h-10 rounded cursor-pointer" />
                      <Input value={settings.theme?.primary_color || '#4F5BD5'} onChange={e => setSettings({ ...settings, theme: { ...settings.theme, primary_color: e.target.value } })} className="flex-1" data-testid="settings-primary-color" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <Label>Secondary Color</Label>
                    <div className="flex gap-2 items-center">
                      <input type="color" value={settings.theme?.secondary_color || '#0D9488'} onChange={e => setSettings({ ...settings, theme: { ...settings.theme, secondary_color: e.target.value } })} className="w-10 h-10 rounded cursor-pointer" />
                      <Input value={settings.theme?.secondary_color || '#0D9488'} onChange={e => setSettings({ ...settings, theme: { ...settings.theme, secondary_color: e.target.value } })} className="flex-1" data-testid="settings-secondary-color" />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <Label>Dark Mode</Label>
                    <div className="flex items-center gap-3 pt-1">
                      <Switch checked={darkMode} onCheckedChange={toggleDark} data-testid="settings-dark-mode-switch" />
                      <span className="text-sm text-muted-foreground">{darkMode ? 'Dark' : 'Light'}</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex gap-3 mt-4">
                <Button onClick={saveSettings} disabled={saving} data-testid="save-settings-btn">
                  <Save className="w-4 h-4 mr-2" /> {saving ? 'Saving...' : 'Save Settings'}
                </Button>
                <Button onClick={handleResetBranding} disabled={saving} variant="outline" className="border-destructive/50 text-destructive hover:bg-destructive/10">
                  Reset to Default
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Subjects Tab */}
        <TabsContent value="subjects" className="space-y-4">
          <div className="flex items-center justify-between">
            <Badge variant="secondary" className="gap-1"><BookOpen className="w-3 h-3" /> {subjects.length} Subjects</Badge>
            <Dialog open={subjectDialog} onOpenChange={setSubjectDialog}>
              <DialogTrigger asChild>
                <Button data-testid="add-subject-btn"><Plus className="w-4 h-4 mr-2" /> Add Subject</Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader><DialogTitle>Add Subject</DialogTitle></DialogHeader>
                <form onSubmit={handleAddSubject} className="space-y-3 mt-2">
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1.5"><Label>Name</Label><Input data-testid="subject-name-input" value={subForm.name} onChange={e => setSubForm({ ...subForm, name: e.target.value })} required /></div>
                    <div className="space-y-1.5"><Label>Code</Label><Input data-testid="subject-code-input" value={subForm.code} onChange={e => setSubForm({ ...subForm, code: e.target.value })} required /></div>
                  </div>
                  <div className="space-y-1.5"><Label>Class</Label><Input data-testid="subject-class-input" value={subForm.class_name} onChange={e => setSubForm({ ...subForm, class_name: e.target.value })} placeholder="e.g. CO-A" /></div>
                  <Button type="submit" className="w-full" data-testid="submit-subject-btn">Add Subject</Button>
                </form>
              </DialogContent>
            </Dialog>
          </div>

          <Card>
            <CardContent className="p-0">
              <Table>
                <TableHeader><TableRow>
                  <TableHead>Name</TableHead><TableHead>Code</TableHead><TableHead>Class</TableHead><TableHead className="w-16" />
                </TableRow></TableHeader>
                <TableBody>
                  {subjects.map(s => (
                    <TableRow key={s.id}>
                      <TableCell className="font-medium">{s.name}</TableCell>
                      <TableCell><Badge variant="outline" className="font-mono text-xs">{s.code}</Badge></TableCell>
                      <TableCell className="text-muted-foreground">{s.class_name || '-'}</TableCell>
                      <TableCell>
                        <Button variant="ghost" size="icon" onClick={() => handleDeleteSubject(s.id)} data-testid={`delete-subject-${s.code}`}><Trash2 className="w-4 h-4 text-destructive" /></Button>
                      </TableCell>
                    </TableRow>
                  ))}
                  {subjects.length === 0 && <TableRow><TableCell colSpan={4} className="text-center py-8 text-muted-foreground">No subjects</TableCell></TableRow>}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Users Tab */}
        <TabsContent value="users" className="space-y-4">
          <div className="flex items-center justify-between">
            <Badge variant="secondary" className="gap-1"><Users className="w-3 h-3" /> {users.length} Users</Badge>
            <Dialog open={userDialog} onOpenChange={setUserDialog}>
              <DialogTrigger asChild>
                <Button data-testid="add-user-btn"><Plus className="w-4 h-4 mr-2" /> Add User</Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader><DialogTitle>Add User</DialogTitle></DialogHeader>
                <form onSubmit={handleAddUser} className="space-y-3 mt-2">
                  <div className="space-y-1.5"><Label>Name</Label><Input data-testid="user-name-input" value={userForm.name} onChange={e => setUserForm({ ...userForm, name: e.target.value })} required /></div>
                  <div className="space-y-1.5"><Label>Email</Label><Input data-testid="user-email-input" type="email" value={userForm.email} onChange={e => setUserForm({ ...userForm, email: e.target.value })} required /></div>
                  <div className="space-y-1.5"><Label>Password</Label><Input data-testid="user-password-input" type="password" value={userForm.password} onChange={e => setUserForm({ ...userForm, password: e.target.value })} required /></div>
                  <div className="space-y-1.5">
                    <Label>Role</Label>
                    <Select value={userForm.role} onValueChange={v => setUserForm({ ...userForm, role: v })}>
                      <SelectTrigger data-testid="user-role-select"><SelectValue /></SelectTrigger>
                      <SelectContent>
                        <SelectItem value="faculty">Faculty</SelectItem>
                        <SelectItem value="admin">Admin</SelectItem>
                        <SelectItem value="student">Student</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>
                  <Button type="submit" className="w-full" data-testid="submit-user-btn">Add User</Button>
                </form>
              </DialogContent>
            </Dialog>
          </div>

          <Card>
            <CardContent className="p-0">
              <Table>
                <TableHeader><TableRow>
                  <TableHead>Name</TableHead><TableHead>Email</TableHead><TableHead>Role</TableHead><TableHead className="w-16" />
                </TableRow></TableHeader>
                <TableBody>
                  {users.map(u => (
                    <TableRow key={u.id}>
                      <TableCell className="font-medium">{u.name}</TableCell>
                      <TableCell className="text-muted-foreground text-sm">{u.email}</TableCell>
                      <TableCell><Badge variant={u.role === 'admin' ? 'default' : 'secondary'} className="capitalize text-xs">{u.role}</Badge></TableCell>
                      <TableCell>
                        <Button variant="ghost" size="icon" onClick={() => handleDeleteUser(u.id)} data-testid={`delete-user-${u.email}`} disabled={u.role === 'admin'}>
                          <Trash2 className="w-4 h-4 text-destructive" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Marks Settings Tab */}
        <TabsContent value="marks" className="space-y-4">
          <Card>
            <CardHeader><CardTitle className="text-base flex items-center gap-2"><Sliders className="w-5 h-5 text-primary" /> Marks Ranges</CardTitle></CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">Define percentage ranges for L1, L2, L3 categorization.</p>
              {['L1', 'L2', 'L3'].map(level => (
                <div key={level} className="grid grid-cols-4 gap-3 items-center p-3 rounded-lg bg-muted/50">
                  <div className="font-medium text-sm">
                    <Badge style={{ background: level === 'L1' ? '#0D9488' : level === 'L2' ? '#F59E0B' : '#EF4444', color: 'white' }}>{level}</Badge>
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Min %</Label>
                    <Input type="number" data-testid={`marks-range-${level}-min`} value={settings.marks_ranges?.[level]?.min ?? ''} onChange={e => setSettings({ ...settings, marks_ranges: { ...settings.marks_ranges, [level]: { ...settings.marks_ranges?.[level], min: parseInt(e.target.value) || 0 } } })} />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Max %</Label>
                    <Input type="number" data-testid={`marks-range-${level}-max`} value={settings.marks_ranges?.[level]?.max ?? ''} onChange={e => setSettings({ ...settings, marks_ranges: { ...settings.marks_ranges, [level]: { ...settings.marks_ranges?.[level], max: parseInt(e.target.value) || 100 } } })} />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Label</Label>
                    <Input data-testid={`marks-range-${level}-label`} value={settings.marks_ranges?.[level]?.label ?? ''} onChange={e => setSettings({ ...settings, marks_ranges: { ...settings.marks_ranges, [level]: { ...settings.marks_ranges?.[level], label: e.target.value } } })} />
                  </div>
                </div>
              ))}
              <Button onClick={saveSettings} disabled={saving} data-testid="save-marks-settings-btn">
                <Save className="w-4 h-4 mr-2" /> {saving ? 'Saving...' : 'Save Marks Settings'}
              </Button>
            </CardContent>
          </Card>
        </TabsContent>

        {/* System Tab */}
        <TabsContent value="system" className="space-y-6">
          {/* Download Project */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2"><Download className="w-5 h-5 text-primary" /> Download Full Project</CardTitle>
              <CardDescription>Download the complete source code as a ZIP file. Includes frontend, backend, README and environment examples.</CardDescription>
            </CardHeader>
            <CardContent>
              <Button onClick={handleDownloadProject} disabled={downloading} data-testid="download-project-btn" className="w-full sm:w-auto">
                <Download className="w-4 h-4 mr-2" />
                {downloading ? 'Generating ZIP...' : 'Download Project ZIP'}
              </Button>
              <p className="text-xs text-muted-foreground mt-3">The downloaded project runs locally with zero configuration changes. Just set up your .env files and start.</p>
            </CardContent>
          </Card>

          {/* Seed Sample Data */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2"><Database className="w-5 h-5 text-primary" /> Sample Data</CardTitle>
              <CardDescription>Populate the database with 20 sample students, 4 subjects, 7 days attendance and marks data.</CardDescription>
            </CardHeader>
            <CardContent>
              <Button variant="outline" onClick={handleSeedData} disabled={seeding} data-testid="seed-data-btn">
                <Database className="w-4 h-4 mr-2" />
                {seeding ? 'Seeding...' : 'Generate Sample Data'}
              </Button>
            </CardContent>
          </Card>

          {/* Reset Database - Danger Zone */}
          <Card className="border-destructive/30">
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2 text-destructive"><AlertTriangle className="w-5 h-5" /> Danger Zone</CardTitle>
              <CardDescription>Permanently delete all data. This action cannot be undone. Only the admin account is preserved.</CardDescription>
            </CardHeader>
            <CardContent>
              <Dialog open={resetDialogOpen} onOpenChange={setResetDialogOpen}>
                <DialogTrigger asChild>
                  <Button variant="destructive" data-testid="reset-database-btn">
                    <AlertTriangle className="w-4 h-4 mr-2" /> Reset Entire Database
                  </Button>
                </DialogTrigger>
                <DialogContent>
                  <DialogHeader>
                    <DialogTitle className="flex items-center gap-2 text-destructive"><AlertTriangle className="w-5 h-5" /> Confirm Database Reset</DialogTitle>
                    <DialogDescription>
                      This will permanently delete ALL students, attendance records, marks, subjects, and non-admin users. This action cannot be undone.
                    </DialogDescription>
                  </DialogHeader>
                  <DialogFooter className="gap-2 sm:gap-0">
                    <Button variant="outline" onClick={() => setResetDialogOpen(false)} data-testid="cancel-reset-btn">Cancel</Button>
                    <Button variant="destructive" onClick={handleResetDatabase} disabled={resetting} data-testid="confirm-reset-btn">
                      {resetting ? 'Resetting...' : 'Yes, Reset Everything'}
                    </Button>
                  </DialogFooter>
                </DialogContent>
              </Dialog>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
