import { useState, useEffect } from 'react';
import api from '@/utils/api';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Upload, BookOpen, Award, TrendingUp } from 'lucide-react';
import { toast } from 'sonner';
import { PieChart, Pie, Cell, ResponsiveContainer, Legend, Tooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import { exportToExcel } from '@/utils/exportUtils';

const CAT_COLORS = { L1: '#0D9488', L2: '#F59E0B', L3: '#EF4444' };
const CAT_LABELS = { L1: 'Excellent', L2: 'Average', L3: 'Below Average' };

export default function MarksPage() {
  const [subjects, setSubjects] = useState([]);
  const [selectedSubject, setSelectedSubject] = useState('');
  const [examType, setExamType] = useState('midterm');
  const [selectedLevel, setSelectedLevel] = useState('all');
  const [marksData, setMarksData] = useState(null);
  const [students, setStudents] = useState([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [form, setForm] = useState({ student_id: '', score: '', max_score: '100' });

  useEffect(() => {
    api.get('/subjects').then(r => setSubjects(r.data)).catch(() => {});
    api.get('/students').then(r => setStudents(r.data)).catch(() => {});
  }, []);

  const fetchMarks = () => {
    if (!selectedSubject) return;
    const params = new URLSearchParams({ exam_type: examType });
    if (selectedLevel !== 'all') params.append('level', selectedLevel);
    api.get(`/marks/subject/${selectedSubject}?${params}`).then(r => setMarksData(r.data)).catch(() => {});
  };

  useEffect(() => { fetchMarks(); }, [selectedSubject, examType, selectedLevel]);

  const handleAdd = async (e) => {
    e.preventDefault();
    try {
      await api.post('/marks', { ...form, score: parseFloat(form.score), max_score: parseFloat(form.max_score), subject_id: selectedSubject, exam_type: examType });
      toast.success('Marks added');
      setDialogOpen(false);
      setForm({ student_id: '', score: '', max_score: '100' });
      fetchMarks();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Failed to add marks');
    }
  };

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file || !selectedSubject) { toast.error('Select a subject first'); return; }
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await api.post(`/marks/upload?subject_id=${selectedSubject}&exam_type=${examType}&max_score=100`, fd, { headers: { 'Content-Type': 'multipart/form-data' } });
      toast.success(`Added ${res.data.added} marks`);
      if (res.data.errors?.length) toast.error(`Errors: ${res.data.errors.join(', ')}`);
      fetchMarks();
    } catch (err) {
      toast.error(err.response?.data?.detail || 'Upload failed');
    }
  };

  const summary = marksData?.summary;
  const pieData = summary ? [
    { name: 'L1 - Excellent', value: summary.l1, color: CAT_COLORS.L1 },
    { name: 'L2 - Average', value: summary.l2, color: CAT_COLORS.L2 },
    { name: 'L3 - Below Avg', value: summary.l3, color: CAT_COLORS.L3 },
  ].filter(d => d.value > 0) : [];

  const barData = marksData?.marks?.map(m => ({
    name: m.student?.roll_no || '', score: m.score, category: m.category
  })) || [];

  return (
    <div className="space-y-6" data-testid="marks-page">
      {/* Controls */}
      <div className="flex flex-wrap gap-3 items-end">
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Subject</p>
          <Select value={selectedSubject} onValueChange={setSelectedSubject}>
            <SelectTrigger className="w-52" data-testid="marks-subject-select">
              <SelectValue placeholder="Select Subject" />
            </SelectTrigger>
            <SelectContent>
              {subjects.map(s => <SelectItem key={s.id} value={s.id}>{s.name} ({s.code})</SelectItem>)}
            </SelectContent>
          </Select>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Exam Type</p>
          <Select value={examType} onValueChange={setExamType}>
            <SelectTrigger className="w-40" data-testid="marks-exam-type-select">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="midterm">Midterm</SelectItem>
              <SelectItem value="final">Final</SelectItem>
              <SelectItem value="quiz">Quiz</SelectItem>
              <SelectItem value="assignment">Assignment</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div>
          <p className="text-xs text-muted-foreground mb-1 font-medium">Level</p>
          <Select value={selectedLevel} onValueChange={setSelectedLevel}>
            <SelectTrigger className="w-32" data-testid="marks-level-select">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Levels</SelectItem>
              <SelectItem value="L1">L1</SelectItem>
              <SelectItem value="L2">L2</SelectItem>
              <SelectItem value="L3">L3</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="flex gap-2 ml-auto">
          <label className="cursor-pointer">
            <input type="file" accept=".csv,.xlsx,.xls" onChange={handleUpload} className="hidden" data-testid="upload-marks-input" />
            <Button variant="outline" asChild><span><Upload className="w-4 h-4 mr-2" /> Upload</span></Button>
          </label>
          <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
            <DialogTrigger asChild>
              <Button disabled={!selectedSubject} data-testid="add-marks-btn"><Plus className="w-4 h-4 mr-2" /> Add Marks</Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>Add Marks</DialogTitle></DialogHeader>
              <form onSubmit={handleAdd} className="space-y-4 mt-2">
                <div className="space-y-1.5">
                  <Label className="text-sm">Student</Label>
                  <Select value={form.student_id} onValueChange={v => setForm({ ...form, student_id: v })}>
                    <SelectTrigger data-testid="marks-student-select"><SelectValue placeholder="Select Student" /></SelectTrigger>
                    <SelectContent>
                      {students.map(s => <SelectItem key={s.id} value={s.id}>{s.roll_no} - {s.name}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1.5">
                    <Label className="text-sm">Score</Label>
                    <Input data-testid="marks-score-input" type="number" value={form.score} onChange={e => setForm({ ...form, score: e.target.value })} required />
                  </div>
                  <div className="space-y-1.5">
                    <Label className="text-sm">Max Score</Label>
                    <Input data-testid="marks-max-score-input" type="number" value={form.max_score} onChange={e => setForm({ ...form, max_score: e.target.value })} />
                  </div>
                </div>
                <Button type="submit" className="w-full" data-testid="submit-marks-btn">Save Marks</Button>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </div>

      {!selectedSubject && (
        <Card><CardContent className="p-12 text-center text-muted-foreground">
          <BookOpen className="w-10 h-10 mx-auto mb-3 opacity-40" />
          <p className="text-lg font-medium">Select a subject to view marks</p>
        </CardContent></Card>
      )}

      {selectedSubject && marksData && (
        <>
          {/* Summary */}
          <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
            <Card><CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">Total</p>
              <p className="text-xl font-bold">{summary?.total || 0}</p>
            </CardContent></Card>
            <Card><CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">Average</p>
              <p className="text-xl font-bold text-primary">{summary?.average || 0}</p>
            </CardContent></Card>
            <Card><CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">L1 (Excellent)</p>
              <p className="text-xl font-bold text-emerald-500">{summary?.l1 || 0}</p>
            </CardContent></Card>
            <Card><CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">L2 (Average)</p>
              <p className="text-xl font-bold text-amber-500">{summary?.l2 || 0}</p>
            </CardContent></Card>
            <Card><CardContent className="p-4 text-center">
              <p className="text-xs text-muted-foreground">L3 (Below)</p>
              <p className="text-xl font-bold text-rose-500">{summary?.l3 || 0}</p>
            </CardContent></Card>
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <Card>
              <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><Award className="w-4 h-4 text-primary" /> Grade Distribution</CardTitle></CardHeader>
              <CardContent>
                {pieData.length > 0 ? (
                  <ResponsiveContainer width="100%" height={220}>
                    <PieChart><Pie data={pieData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={4} dataKey="value">
                      {pieData.map((d, i) => <Cell key={i} fill={d.color} />)}
                    </Pie><Tooltip /><Legend wrapperStyle={{ fontSize: 12 }} /></PieChart>
                  </ResponsiveContainer>
                ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No data</div>}
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="pb-2"><CardTitle className="text-sm flex items-center gap-2"><TrendingUp className="w-4 h-4 text-primary" /> Score Distribution</CardTitle></CardHeader>
              <CardContent>
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height={220}>
                    <BarChart data={barData}>
                      <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                      <XAxis dataKey="name" tick={{ fontSize: 10, fill: 'hsl(var(--muted-foreground))' }} />
                      <YAxis tick={{ fontSize: 11, fill: 'hsl(var(--muted-foreground))' }} />
                      <Tooltip />
                      <Bar dataKey="score" radius={[4, 4, 0, 0]}>
                        {barData.map((d, i) => <Cell key={i} fill={CAT_COLORS[d.category] || '#4F5BD5'} />)}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                ) : <div className="h-48 flex items-center justify-center text-sm text-muted-foreground">No data</div>}
              </CardContent>
            </Card>
          </div>

          {/* Table */}
          {(() => {
            const filteredMarks = marksData?.marks?.filter(m => 
              selectedLevel === 'all' ? true : m.category === selectedLevel
            ) || [];
            
            return (
          <Card>
            <CardHeader className="py-3 px-4 flex flex-row items-center justify-between">
              <CardTitle className="text-sm">Marks List</CardTitle>
              <Button variant="outline" size="sm" onClick={() => {
                const data = filteredMarks.map(m => ({ Roll_No: m.student?.roll_no, Name: m.student?.name, Score: m.score, Max: m.max_score, Category: m.category }));
                exportToExcel(data, `marks_${examType}`);
              }} data-testid="export-marks-btn"><Upload className="w-3.5 h-3.5 mr-1" /> Export</Button>
            </CardHeader>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Roll No</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Score</TableHead>
                    <TableHead>Percentage</TableHead>
                    <TableHead className="text-right">Category</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredMarks.map(m => (
                    <TableRow key={m.id} className="hover:bg-muted/50">
                      <TableCell className="font-mono text-sm">{m.student?.roll_no}</TableCell>
                      <TableCell className="font-medium">{m.student?.name}</TableCell>
                      <TableCell>{m.score}/{m.max_score}</TableCell>
                      <TableCell>{m.max_score > 0 ? Math.round(m.score / m.max_score * 100) : 0}%</TableCell>
                      <TableCell className="text-right">
                        <Badge style={{ background: CAT_COLORS[m.category], color: 'white' }} className="text-xs">
                          {m.category} - {CAT_LABELS[m.category]}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
          );
          })()}
        </>
      )}
    </div>
  );
}
