import { useState, useEffect, useCallback, useMemo } from 'react';
import { format } from 'date-fns';
import api from '@/utils/api';
import { motion } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Calendar } from '@/components/ui/calendar';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import {
  CalendarIcon, Save, Upload, UserCheck, UserX, Clock, Camera, Check, X as XIcon
} from 'lucide-react';
import { toast } from 'sonner';
import { exportToExcel } from '@/utils/exportUtils';

const statusColors = { present: 'bg-emerald-500', absent: 'bg-rose-500', half_day: 'bg-amber-500' };
const statusLabels = { present: 'Present', absent: 'Absent', half_day: 'Half Day' };

export default function AttendancePage() {
  const [date, setDate] = useState(new Date());
  const [subjects, setSubjects] = useState([]);
  const [selectedSubject, setSelectedSubject] = useState('');
  const [classes, setClasses] = useState([]);
  const [selectedClass, setSelectedClass] = useState('');
  const [students, setStudents] = useState([]);
  const [attendance, setAttendance] = useState({});
  const [dailyData, setDailyData] = useState(null);
  const [saving, setSaving] = useState(false);
  const [ocrText, setOcrText] = useState('');
  const [ocrProcessing, setOcrProcessing] = useState(false);
  const [extractedNumbers, setExtractedNumbers] = useState([]);
  const [editedNumbers, setEditedNumbers] = useState('');
  const [ocrStatus, setOcrStatus] = useState('present');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    api.get('/subjects').then(r => setSubjects(r.data)).catch(() => {});
    api.get('/classes').then(r => setClasses(r.data)).catch(() => {});
  }, []);

  useEffect(() => {
    api.get(`/students${selectedClass ? `?class_name=${selectedClass}` : ''}`).then(r => setStudents(r.data)).catch(() => {});
  }, [selectedClass]);

  const dateStr = format(date, 'yyyy-MM-dd');

  const fetchDaily = useCallback(() => {
    const params = new URLSearchParams({ date: dateStr });
    if (selectedSubject) params.set('subject_id', selectedSubject);
    if (selectedClass) params.set('class_name', selectedClass);
    api.get(`/attendance/daily?${params}`).then(r => setDailyData(r.data)).catch(() => {});
  }, [dateStr, selectedSubject, selectedClass]);

  useEffect(() => { fetchDaily(); }, [fetchDaily]);

  const setStatus = (studentId, status) => {
    setAttendance(prev => ({ ...prev, [studentId]: status }));
  };

  const uniqueStudents = useMemo(() => {
    const map = new Map();
    students.forEach(s => {
      if (!map.has(s.roll_no)) map.set(s.roll_no, s);
    });
    return Array.from(map.values()).sort((a, b) => parseInt(a.roll_no) - parseInt(b.roll_no));
  }, [students]);

  const filteredStudents = useMemo(() => {
    const lowerQuery = searchQuery.toLowerCase();
    return uniqueStudents.filter(s => 
      s.name.toLowerCase().includes(lowerQuery) || 
      s.roll_no.toString().includes(lowerQuery)
    );
  }, [uniqueStudents, searchQuery]);

  const markAll = (status) => {
    const all = { ...attendance };
    filteredStudents.forEach(s => { all[s.id] = status; });
    setAttendance(all);
  };

  const handleSave = async () => {
    const entries = Object.entries(attendance).map(([student_id, status]) => ({ student_id, status }));
    if (entries.length === 0) { toast.error('No attendance to save'); return; }
    setSaving(true);
    try {
      await api.post('/attendance', { date: dateStr, subject_id: selectedSubject, entries });
      toast.success(`Attendance saved for ${entries.length} students`);
      fetchDaily();
    } catch (err) {
      toast.error('Failed to save attendance');
    } finally {
      setSaving(false);
    }
  };

  const cleanText = (text) => {
    return text.replace(/[^0-9,\s]/g, "").replace(/\s+/g, " ");
  };

  const extractNumbers = (text) => {
    return text.split(/[\s,]+/).map(num => parseInt(num, 10)).filter(num => !isNaN(num) && num > 0 && num <= 150);
  };

  const uniqueNumbers = (arr) => {
    return [...new Set(arr)];
  };

  const sortedNumbers = (arr) => {
    return arr.sort((a, b) => a - b);
  };

  const processOCR = (rawText) => {
    const cleaned = cleanText(rawText);
    const numbers = extractNumbers(cleaned);
    const unique = uniqueNumbers(numbers);
    return sortedNumbers(unique);
  };

  const handleOCR = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setOcrProcessing(true);
    try {
      const formData = new FormData();
      formData.append("file", file);
      
      // Axios natively handles FormData boundaries securely as long as we don't manually override headers
      const res = await api.post('/ocr', formData);
      
      const text = res.data.text || "";
      setOcrText(text);

      // Prioritize the structured numbers array strictly pre-calculated by the backend, otherwise fallback to UI logic
      const numbers = res.data.numbers && res.data.numbers.length > 0 
          ? res.data.numbers 
          : processOCR(text);
          
      setExtractedNumbers(numbers);
      setEditedNumbers(numbers.join(', '));

      if (text.toLowerCase().includes('absent')) {
        setOcrStatus('absent');
      } else {
        setOcrStatus('present');
      }
      toast.info(`Offline OCR extracted ${numbers.length} roll numbers. Review and Apply.`);
    } catch (err) {
      const msg = err.response?.data?.detail || err.message || 'Unknown OCR Error';
      toast.error(`OCR failed: ${msg}`);
      console.error(err);
    } finally {
      setOcrProcessing(false);
    }
  };

  const applyOcrResults = () => {
    const numbers = editedNumbers.split(',').map(n => n.trim()).filter(n => n);
    let matched = 0;
    const newAtt = { ...attendance };
    students.forEach(s => {
      if (numbers.some(n => s.roll_no.toString() === n || s.roll_no.toString().endsWith(n))) {
        newAtt[s.id] = ocrStatus;
        matched++;
      }
    });
    setAttendance(newAtt);
    toast.success(`Applied ${ocrStatus} to ${matched} students`);
  };

  const handleExportDaily = () => {
    if (!dailyData?.records?.length) return;
    const data = dailyData.records.map(r => ({
      Roll_No: r.student?.roll_no || '', Name: r.student?.name || '',
      Status: statusLabels[r.status] || r.status, Date: r.date
    }));
    exportToExcel(data, `attendance_${dateStr}`);
  };

  return (
    <div className="space-y-6" data-testid="attendance-page">
      <Tabs defaultValue="mark" className="space-y-4">
        <TabsList>
          <TabsTrigger value="mark" data-testid="tab-mark-attendance">Mark Attendance</TabsTrigger>
          <TabsTrigger value="view" data-testid="tab-view-records">View Records</TabsTrigger>
          <TabsTrigger value="ocr" data-testid="tab-ocr-upload">OCR Upload</TabsTrigger>
        </TabsList>

        {/* Mark Attendance Tab */}
        <TabsContent value="mark" className="space-y-4">
          <div className="flex flex-wrap gap-3 items-end">
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Search Student</p>
              <Input
                placeholder="Roll No or Name..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-56"
              />
            </div>
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Date</p>
              <Popover>
                <PopoverTrigger asChild>
                  <Button variant="outline" className="w-44 justify-start text-left" data-testid="attendance-date-picker">
                    <CalendarIcon className="w-4 h-4 mr-2" />
                    {format(date, 'PPP')}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar mode="single" selected={date} onSelect={(d) => d && setDate(d)} />
                </PopoverContent>
              </Popover>
            </div>
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Class</p>
              <Select value={selectedClass || 'all'} onValueChange={v => setSelectedClass(v === 'all' ? '' : v)}>
                <SelectTrigger className="w-36" data-testid="attendance-class-select">
                  <SelectValue placeholder="All Classes" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Classes</SelectItem>
                  {classes.map(c => <SelectItem key={c} value={c}>{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <p className="text-xs text-muted-foreground mb-1 font-medium">Subject</p>
              <Select value={selectedSubject || 'all'} onValueChange={v => setSelectedSubject(v === 'all' ? '' : v)}>
                <SelectTrigger className="w-48" data-testid="attendance-subject-select">
                  <SelectValue placeholder="All Subjects" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Subjects</SelectItem>
                  {subjects.map(s => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={() => markAll('present')} data-testid="mark-all-present">
                <Check className="w-3.5 h-3.5 mr-1" /> All Present
              </Button>
              <Button variant="outline" size="sm" onClick={() => markAll('absent')} data-testid="mark-all-absent">
                <XIcon className="w-3.5 h-3.5 mr-1" /> All Absent
              </Button>
            </div>
          </div>

          <Card>
            <CardContent className="p-0">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="w-24">Roll No</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Class</TableHead>
                    <TableHead className="text-right">Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredStudents.map(s => (
                    <TableRow key={s.id} className="hover:bg-muted/50">
                      <TableCell className="font-mono text-sm">{s.roll_no}</TableCell>
                      <TableCell className="font-medium">{s.name}</TableCell>
                      <TableCell className="text-muted-foreground">{s.class_name}</TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-1">
                          {['present', 'absent', 'half_day'].map(st => (
                            <button
                              key={st}
                              data-testid={`attendance-${s.id}-${st}`}
                              onClick={() => setStatus(s.id, st)}
                              className={`px-2.5 py-1 rounded-md text-xs font-medium ${
                                attendance[s.id] === st
                                  ? `${statusColors[st]} text-white shadow-sm ring-2 ring-offset-1 ring-${statusColors[st].replace('bg-', '')}`
                                  : 'bg-muted text-muted-foreground hover:bg-muted/80'
                              }`}
                            >
                              {statusLabels[st]}
                            </button>
                          ))}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                  {filteredStudents.length === 0 && (
                    <TableRow><TableCell colSpan={4} className="text-center py-8 text-muted-foreground">No students found matching filters.</TableCell></TableRow>
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>

          <div className="sticky bottom-4 flex justify-end">
            <Button onClick={handleSave} disabled={saving || Object.keys(attendance).length === 0} data-testid="save-attendance-btn" className="shadow-lg shadow-primary/25">
              <Save className="w-4 h-4 mr-2" />
              {saving ? 'Saving...' : `Save Attendance (${Object.keys(attendance).length})`}
            </Button>
          </div>
        </TabsContent>

        {/* View Records Tab */}
        <TabsContent value="view" className="space-y-4">
          {dailyData && (
            <>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {[
                  { label: 'Present', value: dailyData.summary.present, icon: UserCheck, color: 'text-emerald-500' },
                  { label: 'Absent', value: dailyData.summary.absent, icon: UserX, color: 'text-rose-500' },
                  { label: 'Half Day', value: dailyData.summary.half_day, icon: Clock, color: 'text-amber-500' },
                  { label: 'Total', value: dailyData.summary.total, icon: UserCheck, color: 'text-primary' },
                ].map(s => (
                  <Card key={s.label}>
                    <CardContent className="p-4 flex items-center gap-3">
                      <s.icon className={`w-5 h-5 ${s.color}`} />
                      <div>
                        <p className="text-xs text-muted-foreground">{s.label}</p>
                        <p className="text-xl font-bold">{s.value}</p>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>

              <Card>
                <CardHeader className="py-3 px-4 flex flex-row items-center justify-between">
                  <CardTitle className="text-sm">Records for {dateStr}</CardTitle>
                  <Button variant="outline" size="sm" onClick={handleExportDaily} data-testid="export-daily-btn">
                    <Upload className="w-3.5 h-3.5 mr-1" /> Export
                  </Button>
                </CardHeader>
                <CardContent className="p-4 space-y-6">
                  {['present', 'absent', 'half_day'].map(statusType => {
                    const groupRecords = dailyData.records.filter(r => r.status === statusType);
                    if (groupRecords.length === 0) return null;
                    return (
                      <div key={statusType} className="border rounded-md overflow-hidden">
                        <div className={`px-4 py-2 font-semibold text-sm ${statusColors[statusType]} text-white flex justify-between`}>
                          <span>{statusLabels[statusType]} Students</span>
                          <span>Total: {groupRecords.length}</span>
                        </div>
                        <Table>
                          <TableHeader className="bg-muted/30">
                            <TableRow>
                              <TableHead className="w-24">Roll No</TableHead>
                              <TableHead>Student Name</TableHead>
                              <TableHead className="text-right">Status</TableHead>
                            </TableRow>
                          </TableHeader>
                          <TableBody>
                            {groupRecords.map(r => (
                              <TableRow key={r.id}>
                                <TableCell className="font-mono text-sm">{r.student?.roll_no}</TableCell>
                                <TableCell className="font-medium">{r.student?.name}</TableCell>
                                <TableCell className="text-right">
                                  <Badge className={`${statusColors[r.status]} text-white text-xs`}>{statusLabels[r.status]}</Badge>
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </div>
                    );
                  })}
                  {dailyData.records.length === 0 && (
                    <div className="text-center py-8 text-muted-foreground border rounded-md">No attendance logged for this date</div>
                  )}
                </CardContent>
              </Card>
            </>
          )}
        </TabsContent>

        {/* OCR Tab */}
        <TabsContent value="ocr" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2">
                <Camera className="w-5 h-5 text-primary" /> OCR Attendance Scanner
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">Upload an attendance sheet image. OCR will extract roll numbers and auto-mark students as present.</p>
              <div className="border-2 border-dashed border-border rounded-xl p-8 text-center">
                <Input
                  type="file"
                  accept="image/*"
                  onChange={handleOCR}
                  className="max-w-xs mx-auto"
                  data-testid="ocr-file-input"
                  disabled={ocrProcessing}
                />
                {ocrProcessing && (
                  <div className="mt-4 flex items-center justify-center gap-2 text-primary">
                    <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                    <span className="text-sm">Processing image...</span>
                  </div>
                )}
              </div>
              {extractedNumbers.length > 0 && (
                <div className="p-4 mt-2 rounded-lg border border-primary/20 bg-primary/5 shadow-sm space-y-3">
                  <h4 className="font-semibold text-sm">Review Extracted Roll Numbers</h4>
                  <div className="flex flex-col sm:flex-row gap-3">
                    <Input 
                      className="flex-1"
                      value={editedNumbers} 
                      onChange={(e) => setEditedNumbers(e.target.value)} 
                      placeholder="e.g. 1, 2, 5, 10" 
                    />
                    <Select value={ocrStatus} onValueChange={setOcrStatus}>
                      <SelectTrigger className="w-full sm:w-36 bg-background">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="present">Present</SelectItem>
                        <SelectItem value="absent">Absent</SelectItem>
                        <SelectItem value="half_day">Half Day</SelectItem>
                      </SelectContent>
                    </Select>
                    <Button onClick={applyOcrResults} className="w-full sm:w-auto">Apply to sheet</Button>
                  </div>
                </div>
              )}

              {ocrText && (
                <div className="p-3 mt-4 rounded-lg bg-muted/50">
                  <p className="text-xs text-muted-foreground mb-1 font-medium">Raw OCR Text:</p>
                  <pre className="text-xs whitespace-pre-wrap max-h-40 overflow-auto">{ocrText}</pre>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
